    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap" rel="stylesheet">
    <style>
        :root{--ink:#1f2937;--muted:#6b7280;--cream:#fffaf3;--orange:#e8782e;--dark:#273345;--line:#f0dfc8}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--cream);font-family:'DM Sans',sans-serif}.container{width:min(1120px,calc(100% - 40px));margin:auto}a{color:inherit;text-decoration:none}nav{height:76px;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;gap:10px;align-items:center;font-weight:700;font-size:22px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border-radius:10px 10px 16px;color:#fff;background:var(--orange)}.nav-links{display:flex;gap:28px;color:#4b5563;font-size:14px;font-weight:600}.nav-links a:hover,.nav-links a.active{color:var(--orange)}.nav-actions{display:flex;gap:15px;align-items:center;font-weight:600}.btn{display:inline-flex;justify-content:center;align-items:center;padding:12px 19px;border-radius:999px;font-size:14px;font-weight:700}.btn-primary{background:var(--dark);color:#fff}.btn-primary:hover{background:var(--orange)}.btn-light{border:1px solid #e5e7eb;background:#fff}.page-head{padding:65px 0 42px;text-align:center;background:#fff0dd}.eyebrow{color:var(--orange);font-size:12px;letter-spacing:.13em;text-transform:uppercase;font-weight:700}h1,h2{font-family:'Playfair Display',serif}h1{font-size:clamp(40px,5vw,62px);margin:13px 0}h2{font-size:36px}.page-head p,.copy{max-width:620px;margin:auto;color:var(--muted);line-height:1.7}.section{padding:65px 0}.products{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.product{padding:13px;border:1px solid #f2e7d9;border-radius:21px;background:#fff}.product-img{display:grid;place-items:center;height:176px;border-radius:14px;background:#fff0df;font-size:75px}.product:nth-child(2) .product-img{background:#f8e6e7}.product:nth-child(3) .product-img{background:#e9f0e0}.product:nth-child(4) .product-img{background:#eee5f8}.product h3{margin:15px 0 7px;font-size:16px}.product small{color:var(--muted)}.product footer{display:flex;justify-content:space-between;margin-top:13px;color:var(--orange);font-weight:700}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:54px;align-items:center}.illustration{min-height:310px;border-radius:30px;background:linear-gradient(145deg,#ffc77f,#e77b35);display:grid;place-items:center;font-size:150px}.info-card{padding:26px;border:1px solid var(--line);border-radius:20px;background:#fff}.info-card h3{margin-top:0}.contact-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.contact-card{padding:25px;border-radius:18px;background:#fff;border:1px solid var(--line)}.contact-card b{font-size:25px}.site-footer{margin-top:40px;padding:30px 0;border-top:1px solid var(--line);color:#64748b;font-size:13px}.footer-inner{display:flex;justify-content:space-between}@media(max-width:800px){.nav-links{display:none}.products{grid-template-columns:repeat(2,1fr)}.two-col,.contact-grid{grid-template-columns:1fr}}@media(max-width:480px){.container{width:min(100% - 28px,1120px)}.nav-actions .btn-light{display:none}.product-img{height:128px;font-size:55px}.section{padding:45px 0}}
    </style>
</head>
<body>
<header class="container"><nav><a class="brand" href="{{ route('home') }}"><span class="brand-mark">✦</span>Floura Bakery</a><div class="nav-links"><a class="{{ request()->routeIs('home') ? 'active' : '' }}" href="{{ route('home') }}">Beranda</a><a class="{{ request()->routeIs('storefront.products') ? 'active' : '' }}" href="{{ route('storefront.products') }}">Produk</a><a class="{{ request()->routeIs('storefront.about') ? 'active' : '' }}" href="{{ route('storefront.about') }}">Tentang Kami</a><a class="{{ request()->routeIs('storefront.contact') ? 'active' : '' }}" href="{{ route('storefront.contact') }}">Kontak</a></div><div class="nav-actions"><a href="{{ route('login') }}">Masuk</a><a class="btn btn-primary" href="{{ route('storefront.products') }}">Pesan Sekarang</a></div></nav></header>
